+}
+
+/* Applied by theme.js before first render */
+:root[data-theme="dark"] {
+  --primary: #2b1d19;
+  --secondary: #3e2c27;
+  --text: #efebe9;
+  --light: #1b1412;
+  --surface: #2a201d;
+  color-scheme: dark;
+}
+
+/* Cross-document view transitions (must be present on every page) */
+@view-transition {
+  navigation: auto;
+}
+
+@media (prefers-reduced-motion: reduce) {
+  @view-transition {
+    navigation: none;
+  }
+}
+
+::view-transition-old(root) {
+  animation: 0.25s ease-in both page-out;
+}
+
+::view-transition-new(root) {
+  animation: 0.35s ease-out both page-in;
+}
+
+@keyframes page-out {
+  to { opacity: 0; transform: translateY(-12px); }
+}
+
+@keyframes page-in {
+  from { opacity: 0; transform: translateY(12px); }
+}
+
+/* Keep the header stable across pages instead of fading it with the root */
+nav {
+  view-transition-name: site-nav;
+}
+
+.logo {
+  view-transition-name: site-logo;
+}
+
+* {
+  box-sizing: border-box;
+  margin: 0;
+  padding: 0;
