+  r1: 'f64', r2: 'f64', r2s: 'f64', cs: 'f64', sn: 'f64', u: 'vec', v: 'vec', nd: 'vec',
+  rd: 'vec', rr: 'vec', tv: 'vec', into: 'i32', nnt: 'f64', ddn: 'f64', cos2t: 'f64', k: 'f64',
+  tdir: 'vec', cc: 'f64', Re: 'f64', Tr: 'f64', P: 'f64',
+}, ({ g, s, V, vset, vnorm, vcall }) => {
