+    s('t', call('intersect', ...V('o'), ...V('d'))),
+    if_(ge(g('t'), f64(1e20)), ret(...ZERO)), // if miss, return black
+    s('base', imul(gget(G_HIT), i32(SPHERE_STRIDE))),
+    vset('x', vadd(V('o'), vscale(V('d'), g('t')))),
+    vnorm('n', vsub(V('x'), sphereVec(g('base'), 'p'))),
+    vset('nl', vscale(V('n'), ternary(lt(dot(V('n'), V('d')), f64(0)), f64(1), f64(-1)))),
