+
+const clamp = (x) => ternary(lt(x, f64(0)), f64(0), ternary(gt(x, f64(1)), f64(1), x));
+const toInt = (x) => i32TruncSat(add(mul(call('pow', clamp(x), f64(1 / 2.2)), f64(255)), f64(0.5)));
+const camDir = (() => {
+  const d = [0, -0.042612, -1];
+  const inv = 1 / Math.sqrt(d[0] * d[0] + d[1] * d[1] + d[2] * d[2]);
+  return d.map((v) => v * inv);
+})();
+
+defineFunc('render_rows', { w: 'i32', h: 'i32', samps: 'i32', y0: 'i32', y1: 'i32' }, [], {
