+    vnorm('cy', cross(V('cx'), camDir.map(f64))),
+    vset('cy', vscale(V('cy'), f64(0.5135))),
+    s('inv', div(f64(1), f64FromI32(g('samps')))),
+    forRange('y', g('y0'), g('y1'), c(
+      gset(G_SEED, lshl(i64FromU32(iand(imul(imul(g('y'), g('y')), g('y')), i32(0xffff))), i64(32))),
