+        vset('acc', ZERO),
+        forRange('sy', i32(0), i32(2), forRange('sx', i32(0), i32(2), c(
+          vset('r', ZERO),
+          forRange('smp', i32(0), g('samps'), c(
+            s('r1', mul(f64(2), call('rand'))), s('dx', tent('r1')),
+            s('r2', mul(f64(2), call('rand'))), s('dy', tent('r2')),
+            s('a', subpixel('sx', 'dx', 'x', 'w')),
+            s('b', subpixel('sy', 'dy', 'y', 'h')),
+            vset('d', vadd(vadd(vscale(V('cx'), g('a')), vscale(V('cy'), g('b'))), camDir.map(f64))),
+            vset('o', vadd(vconst(50, 52, 295.6), vscale(V('d'), f64(140)))),
+            vnorm('d', V('d')),
