+          )),
+          vset('acc', vadd(V('acc'), vscale(V('r').map(clamp), f64(0.25)))),
+        ))),
+        s('px', iadd(i32(IMAGE), imul(iadd(imul(isub(isub(g('h'), g('y')), i32(1)), g('w')), g('x')), i32(4)))),
+        store8(g('px'), 0, toInt(g('acc.x'))),
+        store8(g('px'), 1, toInt(g('acc.y'))),
+        store8(g('px'), 2, toInt(g('acc.z'))),
+        store8(g('px'), 3, i32(255)),
+      )),
+    )),
