+const importSec = vec(imports.map(([n], i) => [name('env'), name(n), 0x00, uleb(importTypes[i])]));
+const funcSec = vec(funcs.map((f) => uleb(f.type)));
+const memSec = vec([[0x00, uleb(PAGES)]]);
+const globalSec = vec([
+  [T.i64, 0x01, i64(0), 0x0b], // erand48 state
+  [T.i32, 0x01, i32(0), 0x0b], // hit sphere id
+]);
+const exportSec = vec([
+  [name('memory'), 0x02, uleb(0)],
+  ...funcs.filter((f) => f.exported).map((f) => [name(f.fname), 0x00, uleb(fnIndex(f.fname))]),
