+  const body = c(vec(f.localTypes.map((t) => [1, T[t]])), f.code);
+  return [uleb(body.length), body];
+}));
+const dataSec = vec([
+  [0x00, i32(SPHERES), 0x0b, vec([...sceneBytes])],
