+.carousel-out-right { animation: carousel-out-right 350ms ease-out both; }
+
+@media (prefers-reduced-motion: reduce) {
+  .carousel-in-right,
+  .carousel-in-left { animation: none; }
+  .carousel-out-left,
+  .carousel-out-right { display: none; }
