+        return [dt, dd];
+      }));
+    }
+
+    form.querySelectorAll('[data-back]').forEach((btn) => {
+      btn.addEventListener('click', () => showStep(Math.max(0, current - 1)));
+    });
+
+    // The browser only fires submit once the enabled fields are valid, so it doubles as "Next".
+    form.addEventListener('submit', async (e) => {
+      e.preventDefault();
+      if (current < steps.length - 1) {
+        showStep(current + 1);
+        return;
+      }
+
+      submitBtn.disabled = true;
+      submitBtn.textContent = 'Joining…';
+      status.className = 'form-status';
+      status.textContent = '';
+
+      try {
+        const res = await fetch(form.action, {
+          method: 'POST',
+          body: new FormData(form),
+          credentials: 'same-origin',
+          headers: { Accept: 'application/json' },
+        });
+        if (!res.ok) throw new Error(`HTTP ${res.status}`);
+
+        form.reset();
+        form.hidden = true;
+        progress.closest('nav').hidden = true;
+        status.className = 'form-status success';
+        status.textContent = 'Welcome to Daily Grind Rewards! Check your email to confirm your account.';
+        // The submit button is gone, so move focus to the confirmation instead of losing it.
+        status.focus();
+      } catch {
+        status.className = 'form-status error';
+        status.textContent = "We couldn't create your account right now. Please try again in a moment.";
+      } finally {
+        submitBtn.disabled = false;
+        submitBtn.textContent = 'Join Rewards';
+      }
+    });
+
+    showStep(0, { focus: false });
+  </script>
