diff --git a/src/hooks/useModalDialog.ts b/src/hooks/useModalDialog.ts
new file mode 100644
index 0000000..2ea68f7
--- /dev/null
+++ b/src/hooks/useModalDialog.ts
@@ -0,0 +1,42 @@
+import { useEffect, useRef } from 'react';
+
+// Pointer position test rather than event.target: the <dialog> is also the target
+// for clicks on its own padding, so a target check would close on those.
+const isOutside = (event: PointerEvent, dialog: HTMLDialogElement) => {
+    const rect = dialog.getBoundingClientRect();
+    return event.clientX < rect.left || event.clientX > rect.right || event.clientY < rect.top || event.clientY > rect.bottom;
+};
+
+/**
+ * Keeps a native <dialog> opened as a modal (showModal) in sync with React state.
+ * The browser handles focus containment, Esc, the inert page and focus return.
+ * Adds a light-dismiss fallback for browsers that don't support `closedby="any"`.
+ */
+export function useModalDialog(open: boolean) {
+    const dialogRef = useRef<HTMLDialogElement>(null);
+
+    useEffect(() => {
+        const dialog = dialogRef.current;
+        if (!dialog) return;
+        if (open && !dialog.open) dialog.showModal();
+        if (!open && dialog.open) dialog.close();
+    }, [open]);
+
+    useEffect(() => {
+        const dialog = dialogRef.current;
+        if (!dialog || 'closedBy' in HTMLDialogElement.prototype) return;
+
+        let pressedOutside = false;
+        const onPointerDown = (event: PointerEvent) => { pressedOutside = isOutside(event, dialog); };
+        // Require press and release outside, so a text-selection drag ending on the backdrop doesn't dismiss
+        const onPointerUp = (event: PointerEvent) => { if (pressedOutside && isOutside(event, dialog)) dialog.close(); };
+        dialog.addEventListener('pointerdown', onPointerDown);
+        dialog.addEventListener('pointerup', onPointerUp);
+        return () => {
+            dialog.removeEventListener('pointerdown', onPointerDown);
+            dialog.removeEventListener('pointerup', onPointerUp);
+        };
+    }, []);
+
+    return dialogRef;
+}
