diff --git a/src/components/ModalDialog.tsx b/src/components/ModalDialog.tsx
new file mode 100644
index 0000000..1d98df3
--- /dev/null
+++ b/src/components/ModalDialog.tsx
@@ -0,0 +1,57 @@
+import React, { useEffect, useRef, type ReactNode, type RefObject } from 'react';
+
+interface Props {
+  labelledBy: string;
+  onClose: () => void;
+  initialFocusRef?: RefObject<HTMLElement | null>;
+  children: ReactNode;
+}
+
+// Native modal <dialog>: the browser provides the top layer, the ::backdrop, inertness of the
+// rest of the page, Escape handling and restoring focus to the trigger when it closes.
+export default function ModalDialog({ labelledBy, onClose, initialFocusRef, children }: Props) {
+  const dialogRef = useRef<HTMLDialogElement>(null);
+
+  useEffect(() => {
+    const dialog = dialogRef.current;
+    if (!dialog) return;
+
+    dialog.showModal();
+    initialFocusRef?.current?.focus();
+
+    return () => {
+      if (dialog.open) dialog.close();
+    };
+  }, []);
+
+  const close = () => dialogRef.current?.close();
+
+  // Light dismiss fallback for browsers without `closedby` support: a click whose target is the
+  // dialog itself (not its content) landed on the backdrop.
+  const handleClick = (event: React.MouseEvent<HTMLDialogElement>) => {
+    if (event.target === event.currentTarget) close();
+  };
+
+  return (
+    <dialog
+      ref={dialogRef}
+      aria-labelledby={labelledBy}
+      closedby="any"
+      onClose={onClose}
+      onClick={handleClick}
+      className="bg-white shadow-xl w-[calc(100%-2rem)] max-w-2xl p-0 m-auto mt-[15vh] overflow-visible backdrop:bg-white/30 backdrop:backdrop-blur-sm"
+    >
+      <button
+        type="button"
+        onClick={close}
+        aria-label="Close"
+        className="absolute -top-2 -right-2 bg-white rounded-full p-1 shadow-md text-gray-500 hover:text-amber-400 hover:scale-110 transition-transform z-10"
+      >
+        <svg aria-hidden="true" xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
+          <path strokeLinecap="round" strokeLinejoin="round" d="M6 18L18 6M6 6l12 12" />
+        </svg>
+      </button>
+      {children}
+    </dialog>
+  );
+}
