+          return new Request(url, base);
+        }
+      }
+
+      function requestJSON(device, path, method, body) {
+        var controller = new AbortController();
+        var timer = setTimeout(function () { controller.abort(); }, TIMEOUT_MS);
+        var init = { method: method || 'GET', signal: controller.signal };
+        if (body !== undefined) {
+          init.headers = { 'Content-Type': 'application/json' };
+          init.body = JSON.stringify(body);
+        }
+        return fetch(buildRequest(device.baseUrl + path, init, device.addressSpace))
+          .then(function (res) {
+            if (!res.ok) throw new Error('Device responded with HTTP ' + res.status);
+            var type = res.headers.get('Content-Type') || '';
+            return type.indexOf('application/json') !== -1 ? res.json() : {};
+          })
+          .catch(function (err) {
+            if (err.name === 'AbortError') throw new Error('Timed out after ' + TIMEOUT_MS / 1000 + 's');
+            if (err instanceof TypeError) {
+              throw new Error('Could not reach the device. Check that it is powered on, on this network, and that ' +
+                'you allowed local network access.' +
+                (location.protocol === 'https:' ? ' Some browsers block secure pages from reaching local HTTP devices.' : ''));
+            }
+            throw err;
+          })
+          .finally(function () { clearTimeout(timer); });
+      }
+
+      // ---- Persistence --------------------------------------------------------
+
+      function loadSettings() {
+        try { return JSON.parse(localStorage.getItem(STORAGE_KEY)) || {}; } catch (e) { return {}; }
+      }
+
+      function saveSettings(patch) {
+        try {
+          localStorage.setItem(STORAGE_KEY, JSON.stringify(Object.assign(loadSettings(), patch)));
+        } catch (e) { /* storage unavailable; ignore */ }
+      }
+
+      // ---- UI -----------------------------------------------------------------
+
+      function renderDetails(container, entries) {
+        container.textContent = '';
+        var dl = document.createElement('dl');
+        entries.forEach(function (pair) {
+          if (pair[1] === undefined || pair[1] === null || pair[1] === '') return;
+          var dt = document.createElement('dt');
+          var dd = document.createElement('dd');
+          dt.textContent = pair[0];
+          dd.textContent = String(pair[1]);
+          dl.appendChild(dt);
+          dl.appendChild(dd);
+        });
+        if (dl.children.length) container.appendChild(dl);
+        else container.textContent = 'Connected. The device did not report any details.';
+      }
+
+      function createDevicePanel(opts) {
+        var $ = function (id) { return document.getElementById(opts.prefix + '-' + id); };
+        var card = $('card');
+        var form = $('form');
+        var connectBtn = $('connect');
+        var disconnectBtn = $('disconnect');
+        var statusEl = $('status');
+        var detailsEl = $('details');
+        var actionsEl = $('actions');
+        var device = null;
+        var pollTimer = null;
+
+        function setState(state, message) {
+          card.classList.remove('connected', 'connecting', 'error');
+          if (state) card.classList.add(state);
+          statusEl.textContent = message;
+          var busy = state === 'connecting';
+          var connected = state === 'connected';
+          connectBtn.disabled = busy;
+          connectBtn.hidden = connected;
+          disconnectBtn.hidden = !connected;
+          actionsEl.hidden = !connected;
+          Array.prototype.forEach.call(form.querySelectorAll('input:not([readonly])'), function (el) {
+            el.disabled = busy || connected;
+          });
+        }
+
+        function stopPolling() {
+          if (pollTimer) clearInterval(pollTimer);
+          pollTimer = null;
+        }
+
+        function refresh() {
+          if (!device) return Promise.resolve();
+          var current = device;
+          return requestJSON(current, opts.statusPath).then(function (data) {
+            if (device !== current) return;
+            renderDetails(detailsEl, opts.describe(data || {}));
+          });
+        }
+
+        function connect(event) {
+          event.preventDefault();
+          var target = opts.readTarget();
+          if (target.error) {
+            setState('error', target.error);
+            return;
+          }
+          stopPolling();
+          device = {
+            baseUrl: 'http://' + target.host + ':' + target.port,
+            addressSpace: opts.addressSpace
+          };
+          setState('connecting', 'Connecting to ' + target.host + ':' + target.port + '…');
+          refresh().then(function () {
+            setState('connected', 'Connected to ' + target.host + ':' + target.port);
+            saveSettings(opts.persist(target));
+            pollTimer = setInterval(function () {
+              refresh().catch(function (err) {
+                stopPolling();
+                device = null;
+                setState('error', 'Connection lost');
+                detailsEl.textContent = err.message;
+              });
+            }, POLL_MS);
+          }).catch(function (err) {
+            device = null;
+            setState('error', 'Connection failed');
+            detailsEl.textContent = err.message;
+          });
+        }
+
+        function disconnect() {
+          stopPolling();
+          device = null;
+          setState(null, 'Not connected');
+          detailsEl.textContent = 'Disconnected.';
+        }
+
+        // Runs a device command and reports the result in the status line.
+        function command(button, label, path, body) {
+          if (!device) return;
+          button.disabled = true;
+          statusEl.textContent = label + '…';
+          requestJSON(device, path, 'POST', body).then(function (data) {
+            statusEl.textContent = (data && typeof data.message === 'string') ? data.message : label + ': done';
+            return refresh();
+          }).catch(function (err) {
+            statusEl.textContent = label + ' failed: ' + err.message;
+          }).finally(function () {
+            button.disabled = false;
+          });
+        }
+
+        form.addEventListener('submit', connect);
+        disconnectBtn.addEventListener('click', disconnect);
+        setState(null, 'Not connected');
+
+        return { command: command };
+      }
+
+      // ---- Wire up devices ----------------------------------------------------
+
+      var saved = loadSettings();
+      var brewerHost = document.getElementById('brewer-host');
+      var brewerPort = document.getElementById('brewer-port');
+      var helperPort = document.getElementById('helper-port');
+
+      brewerHost.value = saved.brewerHost || '192.168.1.50';
+      brewerPort.value = saved.brewerPort || 80;
+      helperPort.value = saved.helperPort || 47800;
+
+      var brewer = createDevicePanel({
+        prefix: 'brewer',
+        addressSpace: 'local',
+        statusPath: '/api/status',
+        readTarget: function () {
+          var octets = parseIPv4(brewerHost.value);
+          var port = parsePort(brewerPort.value);
+          if (!octets) return { error: 'Enter a valid IPv4 address, e.g. 192.168.1.50' };
+          if (!isPrivateLanIPv4(octets)) return { error: 'Only private shop-network addresses are allowed' };
+          if (!port) return { error: 'Enter a port between 1 and 65535' };
+          return { host: octets.join('.'), port: port };
+        },
+        persist: function (t) { return { brewerHost: t.host, brewerPort: t.port }; },
+        describe: function (d) {
+          return [
+            ['Model', d.model],
+            ['Firmware', d.firmware],
+            ['State', d.state],
+            ['Water temp', typeof d.temperatureC === 'number' ? d.temperatureC + ' °C' : undefined],
+            ['Reservoir', typeof d.waterLevelPercent === 'number' ? d.waterLevelPercent + '%' : undefined],
+            ['Current brew', d.currentRecipe]
+          ];
+        }
+      });
+
+      var helper = createDevicePanel({
+        prefix: 'helper',
+        addressSpace: 'loopback',
+        statusPath: '/api/status',
+        readTarget: function () {
+          var port = parsePort(helperPort.value);
+          if (!port) return { error: 'Enter a port between 1 and 65535' };
+          return { host: '127.0.0.1', port: port };
+        },
+        persist: function (t) { return { helperPort: t.port }; },
+        describe: function (d) {
+          return [
+            ['App', d.name || 'Brewing Helper'],
+            ['Version', d.version],
+            ['Saved recipes', typeof d.recipeCount === 'number' ? d.recipeCount : undefined],
+            ['Timer', d.timer]
+          ];
+        }
+      });
+
+      document.getElementById('brewer-actions').addEventListener('submit', function (e) {
+        e.preventDefault();
+        brewer.command(document.getElementById('brew-start'), 'Starting brew', '/api/brew', {
+          recipe: document.getElementById('brew-recipe').value,
+          size: document.getElementById('brew-size').value
+        });
+      });
+
+      document.getElementById('brew-stop').addEventListener('click', function (e) {
+        brewer.command(e.currentTarget, 'Stopping', '/api/stop', {});
+      });
+
+      document.getElementById('helper-actions').addEventListener('submit', function (e) {
+        e.preventDefault();
+        helper.command(document.getElementById('helper-send'), 'Sending recipe', '/api/recipes', {
+          recipe: document.getElementById('helper-recipe').value
+        });
+      });
+
+      document.getElementById('helper-timer').addEventListener('click', function (e) {
+        helper.command(e.currentTarget, 'Starting timer', '/api/timer', {
+          recipe: document.getElementById('helper-recipe').value
+        });
+      });
+    })();
+  </script>
+
 </body>

 </html>

