--- /dev/null
+++ b/sw.js
@@ -0,0 +1,26 @@
+const CACHE = 'daily-grind-v1';
+const SHELL = ['/', '/index.html', '/app-migration.js', '/icons/icon-192.png', '/icons/icon-512.png'];
+
+self.addEventListener('install', (event) => {
+  event.waitUntil(caches.open(CACHE).then((cache) => cache.addAll(SHELL)).then(() => self.skipWaiting()));
+});
+
+self.addEventListener('activate', (event) => {
+  event.waitUntil(
+    caches.keys()
+      .then((keys) => Promise.all(keys.filter((key) => key !== CACHE).map((key) => caches.delete(key))))
+      .then(() => self.clients.claim()),
+  );
+});
+
+// Network first so migration redirects and manifest changes are always seen;
+// fall back to the cached shell when offline.
+self.addEventListener('fetch', (event) => {
+  const { request } = event;
+  if (request.method !== 'GET' || new URL(request.url).origin !== self.location.origin) return;
+
+  event.respondWith(
+    fetch(request).catch(() => caches.match(request)
+      .then((cached) => cached || (request.mode === 'navigate' ? caches.match('/') : Response.error()))),
+  );
+});

