+    function onDrawerClosed() {
+      if (!isOpen()) return;
+      drawer.hidePopover();
+      pageContent.forEach((el) => (el.inert = false));
+      drawer.removeAttribute('aria-modal');
+      openBtn.setAttribute('aria-expanded', 'false');
+      openBtn.focus();
+    }
