+# Security & privacy response headers (Netlify / Cloudflare Pages `_headers` format).
+# If you host elsewhere, apply the same values in your server/CDN config.
+# Keep the CSP in sync with the <meta> fallback in index.html and privacy/third-parties.json
+# (`npm run audit:privacy` checks this).
+
+/*
+  Content-Security-Policy: default-src 'none'; script-src 'self'; style-src 'self'; img-src 'self' https://images.unsplash.com; font-src 'self'; connect-src 'self'; manifest-src 'self'; form-action 'self'; base-uri 'none'; object-src 'none'; frame-ancestors 'none'; upgrade-insecure-requests
+  Strict-Transport-Security: max-age=63072000; includeSubDomains; preload
+  Referrer-Policy: same-origin
+  Permissions-Policy: accelerometer=(), ambient-light-sensor=(), autoplay=(), browsing-topics=(), camera=(), display-capture=(), encrypted-media=(), geolocation=(), gyroscope=(), hid=(), interest-cohort=(), magnetometer=(), microphone=(), midi=(), payment=(), publickey-credentials-get=(), screen-wake-lock=(), serial=(), usb=(), xr-spatial-tracking=()
+  X-Content-Type-Options: nosniff
+  X-Frame-Options: DENY
+  Cross-Origin-Opener-Policy: same-origin
+  Cross-Origin-Resource-Policy: same-origin
+  X-DNS-Prefetch-Control: off
+  X-Permitted-Cross-Domain-Policies: none
+  Origin-Agent-Cluster: ?1
+
+# HTML may show signed-in navigation; never let shared/intermediate caches keep it.
+/
+  Cache-Control: private, no-cache
+/index.html
+  Cache-Control: private, no-cache
+
+# Account and auth pages contain personal data: don't store anywhere, wipe on logout.
+/account*
+  Cache-Control: no-store
+# Clear-Site-Data omits "storage" so the device-level privacy choice survives; privacy.js clears session keys.
+/logout
+  Cache-Control: no-store
+  Clear-Site-Data: "cache", "cookies"
+
+/assets/*
+  Cache-Control: public, max-age=31536000, immutable
+
+/.well-known/gpc.json
+  Content-Type: application/json
+  Cache-Control: public, max-age=86400
