@@ -0,0 +1,189 @@
+'use strict';
+
+const http = require('node:http');
+const fs = require('node:fs');
+const path = require('node:path');
+
+const PORT = Number(process.env.PORT) || 11222;
+const PUBLIC_DIR = path.join(__dirname, 'public');
+const DATA_DIR = path.join(__dirname, 'data');
+const SUBSCRIBERS_FILE = path.join(DATA_DIR, 'subscribers.jsonl');
+const MAX_BODY_BYTES = 4 * 1024;
+const EMAIL_PATTERN = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
+
+// The page may only talk to this origin, plus Unsplash for photos.
+// No inline scripts/styles are allowed, so an injected <script> or
+// attribute handler cannot run, and anything that does run cannot
+// fetch, beacon, post a form, or load images to another host.
+const CONTENT_SECURITY_POLICY = [
+  "default-src 'none'",
+  "script-src 'self'",
+  "style-src 'self'",
+  "img-src 'self' https://images.unsplash.com",
+  "font-src 'self'",
+  "connect-src 'self'",
+  "manifest-src 'self'",
+  "form-action 'self'",
+  "base-uri 'none'",
+  "frame-ancestors 'none'",
+  "object-src 'none'",
+  "worker-src 'none'",
+  "frame-src 'none'",
+  "media-src 'none'",
+].join('; ');
+
+const SECURITY_HEADERS = {
+  'Content-Security-Policy': CONTENT_SECURITY_POLICY,
+  'X-Content-Type-Options': 'nosniff',
+  'Referrer-Policy': 'same-origin',
+  'X-Frame-Options': 'DENY',
+  'X-DNS-Prefetch-Control': 'off',
+  'Cross-Origin-Opener-Policy': 'same-origin',
+  'Cross-Origin-Resource-Policy': 'same-origin',
+  'Permissions-Policy': 'camera=(), microphone=(), geolocation=(), payment=(), usb=(), interest-cohort=()',
+};
+
+const MIME_TYPES = {
+  '.html': 'text/html; charset=utf-8',
+  '.css': 'text/css; charset=utf-8',
+  '.js': 'text/javascript; charset=utf-8',
+  '.json': 'application/json; charset=utf-8',
+  '.svg': 'image/svg+xml',
+  '.png': 'image/png',
+  '.jpg': 'image/jpeg',
+  '.ico': 'image/x-icon',
+};
+
+function send(res, status, body, headers = {}) {
+  res.writeHead(status, { ...SECURITY_HEADERS, ...headers });
+  res.end(body);
+}
+
+function sendJson(res, status, payload) {
+  send(res, status, JSON.stringify(payload), {
+    'Content-Type': 'application/json; charset=utf-8',
+    'Cache-Control': 'no-store',
+  });
+}
+
+function serveStatic(req, res, pathname) {
+  if (req.method !== 'GET' && req.method !== 'HEAD') {
+    return send(res, 405, 'Method Not Allowed', { Allow: 'GET, HEAD', 'Content-Type': 'text/plain; charset=utf-8' });
+  }
+
+  let decoded;
+  try {
+    decoded = decodeURIComponent(pathname);
+  } catch {
+    return send(res, 400, 'Bad Request', { 'Content-Type': 'text/plain; charset=utf-8' });
+  }
+  if (decoded.endsWith('/')) decoded += 'index.html';
+
+  const filePath = path.join(PUBLIC_DIR, path.normalize(decoded));
+  if (!filePath.startsWith(PUBLIC_DIR + path.sep)) {
+    return send(res, 403, 'Forbidden', { 'Content-Type': 'text/plain; charset=utf-8' });
+  }
+
+  fs.readFile(filePath, (err, data) => {
+    if (err) {
+      return send(res, 404, 'Not Found', { 'Content-Type': 'text/plain; charset=utf-8' });
+    }
+    const type = MIME_TYPES[path.extname(filePath).toLowerCase()] || 'application/octet-stream';
+    send(res, 200, req.method === 'HEAD' ? undefined : data, {
+      'Content-Type': type,
+      'Cache-Control': type.startsWith('text/html') ? 'no-cache' : 'public, max-age=3600',
+    });
+  });
+}
+
+function readBody(req) {
+  return new Promise((resolve, reject) => {
+    let size = 0;
+    const chunks = [];
+    req.on('data', (chunk) => {
+      size += chunk.length;
+      if (size > MAX_BODY_BYTES) {
+        reject(Object.assign(new Error('Payload too large'), { status: 413 }));
+        req.destroy();
+        return;
+      }
+      chunks.push(chunk);
+    });
+    req.on('end', () => resolve(Buffer.concat(chunks).toString('utf8')));
+    req.on('error', reject);
+  });
+}
+
+async function handleNewsletter(req, res) {
+  if (req.method !== 'POST') {
+    res.setHeader('Allow', 'POST');
+    return sendJson(res, 405, { error: 'Method not allowed.' });
+  }
+
+  // Reject cross-site submissions.
+  const site = req.headers['sec-fetch-site'];
+  if (site && site !== 'same-origin' && site !== 'none') {
+    return sendJson(res, 403, { error: 'Cross-site requests are not allowed.' });
+  }
+
+  const contentType = (req.headers['content-type'] || '').split(';')[0].trim();
+  let raw;
+  try {
+    raw = await readBody(req);
+  } catch (err) {
+    return sendJson(res, err.status || 400, { error: 'Your request could not be read. Please try again.' });
+  }
+
+  let email;
+  try {
+    if (contentType === 'application/json') {
+      email = JSON.parse(raw).email;
+    } else if (contentType === 'application/x-www-form-urlencoded') {
+      email = new URLSearchParams(raw).get('email');
+    } else {
+      return sendJson(res, 415, { error: 'Unsupported request format.' });
+    }
+  } catch {
+    return sendJson(res, 400, { error: 'Your request could not be read. Please try again.' });
+  }
+
+  email = typeof email === 'string' ? email.trim().toLowerCase() : '';
+  if (email.length > 254 || !EMAIL_PATTERN.test(email)) {
+    return sendJson(res, 422, { error: 'Please enter a valid email address.' });
+  }
+
+  try {
+    await fs.promises.mkdir(DATA_DIR, { recursive: true });
+    await fs.promises.appendFile(
+      SUBSCRIBERS_FILE,
+      JSON.stringify({ email, subscribedAt: new Date().toISOString() }) + '\n',
+    );
+  } catch (err) {
+    console.error('Failed to save subscriber:', err);
+    return sendJson(res, 500, { error: 'We couldn’t save your signup right now. Please try again later.' });
+  }
+
+  return sendJson(res, 201, { message: 'Thanks for subscribing! Watch your inbox for fresh brews.' });
+}
+
+const server = http.createServer((req, res) => {
+  const { pathname } = new URL(req.url, 'http://localhost');
+
+  if (pathname === '/api/newsletter') {
+    handleNewsletter(req, res).catch((err) => {
+      console.error(err);
+      if (!res.headersSent) sendJson(res, 500, { error: 'Something went wrong. Please try again later.' });
+    });
+    return;
+  }
+
+  serveStatic(req, res, pathname);
+});
+
+if (require.main === module) {
+  server.listen(PORT, () => {
+    console.log(`The Daily Grind is running at http://localhost:${PORT}`);
+  });
+}
+
+module.exports = { server, CONTENT_SECURITY_POLICY };

