+  <script>
+    // Scroll spy: highlight the nav link for the section currently in view.
+    (function () {
+      const nav = document.querySelector('nav');
+      const links = Array.from(document.querySelectorAll('nav a.nav-link'));
+      const sections = links
+        .map(link => document.querySelector(link.getAttribute('href')))
+        .filter(Boolean);
+
+      function setActive(id) {
+        links.forEach(link => {
+          const isActive = link.getAttribute('href') === '#' + id;
+          link.classList.toggle('active', isActive);
+          if (isActive) {
+            link.setAttribute('aria-current', 'location');
+          } else {
+            link.removeAttribute('aria-current');
+          }
+        });
+      }
+
+      function update() {
+        // A section counts as "current" once its top passes just below the sticky nav.
+        const offset = nav.offsetHeight + window.innerHeight * 0.25;
+        const atBottom = window.innerHeight + window.scrollY >= document.documentElement.scrollHeight - 2;
+        let current = null;
+
+        if (atBottom) {
+          current = sections[sections.length - 1];
+        } else {
+          for (const section of sections) {
+            if (section.getBoundingClientRect().top <= offset) {
+              current = section;
+            }
+          }
+        }
+
+        // Clear the highlight when scrolled above the first section or past the last one (e.g. hero).
+        if (current && current.getBoundingClientRect().bottom <= nav.offsetHeight) {
+          current = null;
+        }
+        setActive(current ? current.id : null);
+      }
+
+      let ticking = false;
+      function onScroll() {
+        if (!ticking) {
+          ticking = true;
+          requestAnimationFrame(() => {
+            update();
+            ticking = false;
+          });
+        }
+      }
+
+      window.addEventListener('scroll', onScroll, { passive: true });
+      window.addEventListener('resize', onScroll);
+      window.addEventListener('load', update);
+      update();
+    })();
+  </script>
+
