+++ b/src/utils/phone-verification.ts
@@ -0,0 +1,96 @@
+import { createHash, randomInt, timingSafeEqual } from 'node:crypto';
+
+export const CODE_LENGTH = 6;
+export const CODE_TTL_MS = 5 * 60 * 1000;
+export const RESEND_COOLDOWN_MS = 30 * 1000;
+export const MAX_ATTEMPTS = 5;
+
+export interface PendingVerification {
+  phone: string;
+  codeHash: string;
+  expiresAt: number;
+  sentAt: number;
+  attempts: number;
+}
+
+/**
+ * Normalizes user input to E.164 (e.g. "+15551234567").
+ * Numbers without a leading "+" are assumed to be North American (+1).
+ */
+export function normalizePhone(input: unknown): string | null {
+  if (typeof input !== 'string') return null;
+  const trimmed = input.trim();
+  const hasPlus = trimmed.startsWith('+');
+  const digits = trimmed.replace(/\D/g, '');
+
+  let e164: string;
+  if (hasPlus) {
+    e164 = `+${digits}`;
+  } else if (digits.length === 10) {
+    e164 = `+1${digits}`;
+  } else if (digits.length === 11 && digits.startsWith('1')) {
+    e164 = `+${digits}`;
+  } else {
+    return null;
+  }
+
+  return /^\+[1-9]\d{7,14}$/.test(e164) ? e164 : null;
+}
+
+export function generateCode(): string {
+  return randomInt(0, 10 ** CODE_LENGTH).toString().padStart(CODE_LENGTH, '0');
+}
+
+export function hashCode(phone: string, code: string): string {
+  return createHash('sha256').update(`${phone}:${code}`).digest('hex');
+}
+
+export function codeMatches(pending: PendingVerification, code: string): boolean {
+  const expected = Buffer.from(pending.codeHash, 'hex');
+  const actual = Buffer.from(hashCode(pending.phone, code), 'hex');
+  return expected.length === actual.length && timingSafeEqual(expected, actual);
+}
+
+/**
+ * Builds an SMS body compatible with the WebOTP API: the final line
+ * "@<host> #<code>" binds the code to this origin so the browser can
+ * offer to fill it in automatically.
+ */
+export function buildSmsBody(code: string, host: string): string {
+  return `Your DevTools Times verification code is ${code}. It expires in 5 minutes.\n\n@${host} #${code}`;
+}
+
+/**
+ * Sends an SMS via Twilio when credentials are configured. Otherwise the
+ * message is logged to the server console so the flow works in development.
+ */
+export async function sendSms(to: string, body: string): Promise<void> {
+  const sid = process.env.TWILIO_ACCOUNT_SID;
+  const token = process.env.TWILIO_AUTH_TOKEN;
+  const from = process.env.TWILIO_FROM_NUMBER;
+
+  if (!sid || !token || !from) {
+    console.info(`[sms] (no provider configured) to=${to}\n${body}`);
+    return;
+  }
+
+  const response = await fetch(`https://api.twilio.com/2010-04-01/Accounts/${sid}/Messages.json`, {
+    method: 'POST',
+    headers: {
+      Authorization: `Basic ${Buffer.from(`${sid}:${token}`).toString('base64')}`,
+      'Content-Type': 'application/x-www-form-urlencoded',
+    },
+    body: new URLSearchParams({ To: to, From: from, Body: body }),
+  });
+
+  if (!response.ok) {
+    throw new Error(`SMS provider responded with ${response.status}`);
+  }
+}
+
+export function json(data: unknown, status = 200): Response {
+  return new Response(JSON.stringify(data), {
+    status,
+    headers: { 'Content-Type': 'application/json' },
+  });
+}

