+      'use strict';
+
+      // Ordering is handled by a separate app that runs in a popup window.
+      var TRUSTED_ORDER_ORIGIN = 'https://order.thedailygrind.com';
+      // Registrable domain of this site; subdomains of it count as same-site.
+      var SITE_DOMAIN = 'thedailygrind.com';
+      // External hosts we are happy to link to (exact host or subdomain).
+      var ALLOWED_EXTERNAL_HOSTS = ['unsplash.com', 'instagram.com', 'facebook.com'];
+      var WIDGET_MAX_HEIGHT = 600;
+
+      function parseUrl(value, base) {
+        if (typeof value !== 'string' || value.trim() === '') return null;
+        // Backslashes are normalised to slashes by URL parsers ("/\evil.com"
+        // becomes "//evil.com"), and control characters are stripped; reject
+        // both outright rather than reasoning about how they parse.
+        if (/[\\\u0000-\u001f\u007f]/.test(value)) return null;
+        try {
+          return new URL(value, base || window.location.href);
+        } catch (e) {
+          return null;
+        }
+      }
+
+      function isHttpProtocol(url) {
+        return url.protocol === 'https:' || url.protocol === 'http:';
+      }
+
+      // Exact host match or a true subdomain (".example.com" suffix), so that
+      // "evil-example.com" or "example.com.evil.net" never match.
+      function hostMatches(hostname, domain) {
+        var host = hostname.toLowerCase().replace(/\.$/, '');
+        var d = domain.toLowerCase();
+        return host === d || (host.length > d.length && host.slice(-(d.length + 1)) === '.' + d);
+      }
+
+      function isTrustedOrderOrigin(origin) {
+        // Compare full serialized origins (scheme + host + port) exactly.
+        return typeof origin === 'string' && origin === TRUSTED_ORDER_ORIGIN;
+      }
+
+      function isSameSite(url) {
+        if (!isHttpProtocol(url)) return false;
+        // Never allow a downgrade from https to http.
+        if (window.location.protocol === 'https:' && url.protocol !== 'https:') return false;
+        if (url.username || url.password) return false;
+        return url.hostname === window.location.hostname || hostMatches(url.hostname, SITE_DOMAIN);
+      }
+
+      // Returns a safe absolute href for a same-site redirect, or null.
+      function validateRedirect(value) {
+        var url = parseUrl(value);
+        return url && isSameSite(url) ? url.href : null;
+      }
+
+      function isAllowedExternal(url) {
+        if (url.protocol !== 'https:' || url.username || url.password) return false;
+        return ALLOWED_EXTERNAL_HOSTS.some(function (d) { return hostMatches(url.hostname, d); });
+      }
+
+      function safeNavigate(value) {
+        var href = validateRedirect(value);
+        if (href) {
+          window.location.assign(href);
+        } else {
+          console.warn('Blocked redirect to untrusted URL:', value);
+        }
+      }
+
+      // --- Links -------------------------------------------------------------
+
+      function secureLinks(root) {
+        var links = root.querySelectorAll('a[href]');
+        for (var i = 0; i < links.length; i++) {
+          var a = links[i];
+          var url = parseUrl(a.getAttribute('href'));
+          if (!url) {
+            a.removeAttribute('href');
+            continue;
+          }
+          if (isSameSite(url)) continue;
+          if (url.protocol === 'mailto:' || url.protocol === 'tel:') continue;
+          if (isAllowedExternal(url)) {
+            a.setAttribute('target', '_blank');
+            a.setAttribute('rel', 'noopener noreferrer');
+          } else {
+            // javascript:, data:, unknown hosts, etc.
+            a.removeAttribute('href');
+            a.setAttribute('aria-disabled', 'true');
+          }
+        }
+      }
+
+      secureLinks(document);
+
+      // Honour ?redirect= only when it points back to this site.
+      var params = new URLSearchParams(window.location.search);
+      if (params.has('redirect')) safeNavigate(params.get('redirect'));
+
+      // --- Ordering popup ------------------------------------------------------
+
+      var orderWindow = null;
+      var orderStatus = document.getElementById('order-status');
+
+      document.getElementById('order-now').addEventListener('click', function (e) {
+        var w = window.open(TRUSTED_ORDER_ORIGIN + '/start', 'daily-grind-order', 'width=480,height=720');
+        if (w) {
+          e.preventDefault();
+          orderWindow = w;
+        }
+        // If the popup was blocked, fall back to the normal /order-online link.
+      });
+
+      function handleOrderMessage(event) {
+        // Only the popup we opened, served from the trusted origin.
+        if (!orderWindow || event.source !== orderWindow) return;
+        var data = event.data;
+        if (!data || typeof data !== 'object' || typeof data.type !== 'string') return;
+
+        switch (data.type) {
+          case 'order:status':
+            if (typeof data.message === 'string') {
+              orderStatus.textContent = data.message.slice(0, 200);
+            }
+            break;
+          case 'order:complete':
+            orderStatus.textContent = 'Thanks! Your order has been placed.';
+            orderWindow = null;
+            if (data.redirect !== undefined) safeNavigate(data.redirect);
+            break;
+        }
+      }
+
+      // --- Sandboxed rewards widget -------------------------------------------
+
+      var widgetFrame = document.getElementById('rewards-widget');
+      // Sandboxed frames without allow-same-origin all report origin "null",
+      // so origin alone cannot tell them apart. Pin the WindowProxy that sent
+      // the init message and only accept messages from that exact window.
+      var pinnedWidget = null;
+
+      function handleWidgetMessage(event) {
+        var data = event.data;
+        if (!data || typeof data !== 'object' || typeof data.type !== 'string') return;
+
+        if (data.type === 'widget:init') {
+          // Only our own widget frame may (re-)initialise; init from any other
+          // sandboxed frame is ignored and never changes the pinned sender.
+          if (!widgetFrame.contentWindow || event.source !== widgetFrame.contentWindow) return;
+          pinnedWidget = event.source;
+          pinnedWidget.postMessage({ type: 'widget:ack' }, '*');
+          return;
+        }
+
+        if (!pinnedWidget || event.source !== pinnedWidget) return;
+
+        if (data.type === 'widget:resize') {
+          var h = Number(data.height);
+          if (isFinite(h) && h > 0) {
+            widgetFrame.style.height = Math.min(Math.ceil(h), WIDGET_MAX_HEIGHT) + 'px';
+          }
+        }
+      }
+
+      window.addEventListener('message', function (event) {
+        if (isTrustedOrderOrigin(event.origin)) {
+          handleOrderMessage(event);
+        } else if (event.origin === 'null') {
+          handleWidgetMessage(event);
+        }
+        // Everything else is ignored.
+      });
+    })();
+  </script>
+
 </body>

